	if (!isNaN(parseInt(i))) {
		return parseInt(i);
	}
});

array2 = $.map(array2, function (i) {
	if (!isNaN(parseInt(i))) {
		return parseInt(i);
	}
});

var combinedArray = $.merge(array1, array2);
combinedArray = [...new Set(combinedArray)];
for (let n = 0; n < combinedArray.length; n++) {
	for (let i = 0; i < combinedArray.length; i++) {
